const fs=require('fs'),cp=require('child_process');
const decls=fs.readFileSync('/tmp/decls2.txt','utf8').trim().split('\n').map(l=>{const [f,ln,pkg,recv,name]=l.split('|');return{f,ln:+ln,pkg,recv,name,dir:f.replace(/\/[^/]+$/,'')}});
const files=cp.execSync('find . -name "*.go" -not -path "./web/*"').toString().trim().split('\n');
const src={}; for(const f of files) src[f]=fs.readFileSync(f,'utf8').split('\n');
const res=[];
for(const d of decls){
  let n=0; const hits=[];
  for(const f of files){
    const lines=src[f]; const dir=f.replace(/^\.\//,'').replace(/\/[^/]+$/,'');
    const samePkg=(dir===d.dir);
    const body=lines.join('\n');
    let pat;
    if(d.recv){ pat=new RegExp('\\.\\s*'+d.name+'\\s*\\(','g'); }
    else if(samePkg){ pat=new RegExp('(?<![\\w.])'+d.name+'\\s*\\(','g'); }
    else {
      // must import the package
      if(!body.includes('/'+d.dir.replace(/^internal\//,'internal/')+'"')) continue;
      pat=new RegExp('(?<![\\w.])'+d.pkg+'\\s*\\.\\s*'+d.name+'\\s*\\(','g');
    }
    for(let i=0;i<lines.length;i++){
      const l=lines[i]; if(/^func /.test(l)) continue; const t=l.trim(); if(t.startsWith('//')) continue;
      const m=l.match(pat); if(m){n+=m.length; hits.push(f+':'+(i+1)+': '+t.slice(0,100));}
    }
  }
  res.push({...d,n,hits});
}
res.sort((a,b)=>b.n-a.n);
for(const r of res.slice(0,25)) console.log(r.n, (r.recv?'('+r.recv+').':r.pkg+'.')+r.name, r.f+':'+r.ln);
fs.writeFileSync('/tmp/res.json',JSON.stringify(res));
EOF
